561	func escapeSQLLikePattern(s string) string {
562		s = strings.ReplaceAll(s, "\\", "\\\\")
563		s = strings.ReplaceAll(s, "%", "\\%")
564		s = strings.ReplaceAll(s, "_", "\\_")
565		return s
