568	// v2.0.39: 交易表「安全可 SELECT」列名常量 + 白名单契约。
569	//
570	// 为什么必须显式白名单：TAgentHttpTransactionDataItem 中包含 4 个 longtext 字段
571	//   - request_body
572	//   - request_src_protocol_body
573	//   - response_body
574	//   - response_src_protocol_body
575	//
576	// 单字段 ~1MB，整行可达 4MB。任何不带 Select(...) 的 Find/First 都将一次性拉满 IO。
577	//
578	// 约束：
579	//   - 列表类查询（QueryAgentHttpTransactions / GetProtocolAnalysisStats 等）：
580	//     必须使用下面 selectTransactionColumns() 的返回值做 Select(...)；
581	//   - 详情类查询（GetAgentHttpTransactionByID / BodyByID / DetailByID）：
582	//     只能按 ID 单条取，按"请求时按 ID 取一次"的白名单契约；
583	//   - 禁止新增 "全表 SELECT *" 或 "列表查询不带 Select 限定列" 的查询路径。
584	//
585	// 新增列只允许 append 到 selectTransactionColumns() 中，禁止向白名单中加入
586	// 4 个 longtext 字段。CI 合约由 TestTransactionColumnWhitelist_ExcludesLongText 保证。
587	func selectTransactionColumns() string {
588		return "id, created_at, updated_at, deleted_at, user_id, user_name, model_name, " +
589			"dst_model_name, api_key, dst_endpoint_id, dst_endpoint_algorithm_type, protocol_type, " +
590			"request_method, request_url, request_remote_addr, request_content_length, " +
591			"response_status, response_content_length, " +
592			"tokens_input_size, tokens_output_size, tokens_all_size, " +
593			"request_start_at, request_end_at, response_start_at, response_end_at, " +
594			"elapsed_ms, tool_identifier, request_tools, session_id, agent_tool_name, agent_tool_info"
595	}
