597	// QueryAgentHttpTransactions 根据用户名和模型索引名称查询该哈希分表中的记录（支持分页和过滤）
598	//
599	// filterInputTokensNonzero / filterOutputTokensNonzero 为三态整数：
600	//
601	//	0 = 全部（不过滤）；1 = 仅保留非零（>0）；2 = 仅保留为零（=0）
602	func QueryAgentHttpTransactions(
603		userName, modelName string,
604		subTableNum, page, pageSize int,
605		filterURL, filterMethod, filterStatus string,
606		filterStatusNot bool,
607		filterProtocolType int,
608		filterDstModelName string,
609		filterTools string,
610		filterAgentToolName string,
611		days int,
612		filterInputTokensNonzero int,
613		filterOutputTokensNonzero int,
614	) ([]TAgentHttpTransactionDataItem, int64, error) {
615		if DB == nil {
616			return nil, 0, fmt.Errorf("database not initialized")
617		}
618		if subTableNum <= 0 {
619			subTableNum = DEFAULT_SUB_TABLE_NUM
620		}
621		if page < 1 {
622			page = 1
623		}
624		if pageSize < 1 {
625			pageSize = 5
626		}
627	
628		tableName := GetAgentHttpTableName(userName, modelName, subTableNum)
629	
630		startTime := time.Now()
631	
632		query := DB.Table(tableName).Where("user_name = ? AND model_name = ?", userName, modelName)
633		// v2.0.41：span 编码同时支持「天」(days>0) 与「小时」(days<0)，统一走 resolveStatsSpanCutoff
634		if cutoff, ok := resolveStatsSpanCutoff(days); ok {
635			query = query.Where("created_at >= ?", cutoff)
636		}
637		if filterURL != "" {
638			query = query.Where("request_url LIKE ?", "%"+filterURL+"%")
639		}
640		if filterMethod != "" {
641			query = query.Where("request_method = ?", filterMethod)
642		}
643		if filterStatus != "" {
644			if filterStatusNot {
645				query = query.Where("response_status != ?", filterStatus)
646			} else {
647				query = query.Where("response_status = ?", filterStatus)
648			}
649		}
650		if filterProtocolType > 0 {
651			query = query.Where("protocol_type = ?", filterProtocolType)
652		}
653		if filterDstModelName != "" {
654			query = query.Where("dst_model_name = ?", filterDstModelName)
655		}
656		if tools := parseRequestToolsFilter(filterTools); len(tools) > 0 {
657			for _, tool := range tools {
658				likeTool := escapeSQLLikePattern(tool)
659				query = query.Where(
660					"(request_tools = ? OR request_tools LIKE ? ESCAPE '\\\\' OR request_tools LIKE ? ESCAPE '\\\\' OR request_tools LIKE ? ESCAPE '\\\\')",
661					tool,
662					likeTool+",%",
663					"%,"+likeTool+",%",
664					"%,"+likeTool,
665				)
666			}
667		}
668		if filterAgentToolName != "" {
669			query = query.Where("agent_tool_name = ?", filterAgentToolName)
670		}
671		if filterInputTokensNonzero == 1 {
672			query = query.Where("tokens_input_size > 0")
673		} else if filterInputTokensNonzero == 2 {
674			query = query.Where("tokens_input_size = 0")
675		}
676		if filterOutputTokensNonzero == 1 {
677			query = query.Where("tokens_output_size > 0")
678		} else if filterOutputTokensNonzero == 2 {
679			query = query.Where("tokens_output_size = 0")
680		}
681	
682		// 查询总数
683		countStart := time.Now()
684		var total int64
685		if err := query.Count(&total).Error; err != nil {
686			return nil, 0, fmt.Errorf("failed to count records: %w", err)
687		}
688		countElapsed := time.Since(countStart)
689	
690		if total == 0 {
691			logger.Printf("[DB] QueryAgentHttpTransactions table=%s days=%d total=0 records=0 count=%v query=0 total=%v",
692				tableName, days, countElapsed, time.Since(startTime))
693			return []TAgentHttpTransactionDataItem{}, total, nil
694		}
695	
696		totalPages := int((total + int64(pageSize) - 1) / int64(pageSize))
697		if page > totalPages {
698			page = totalPages
699		}
700	
701		var records []TAgentHttpTransactionDataItem
702		offset := (page - 1) * pageSize
703		// 列表查询排除大字段（request_body/response_body/request_headers/response_headers），减少网络传输和内存占用
704		queryStart := time.Now()
705		listQuery := DB.Table(tableName).Where("user_name = ? AND model_name = ?", userName, modelName)
706		// v2.0.41：span 编码同时支持「天」(days>0) 与「小时」(days<0)，统一走 resolveStatsSpanCutoff
707		if cutoff, ok := resolveStatsSpanCutoff(days); ok {
708			listQuery = listQuery.Where("created_at >= ?", cutoff)
709		}
710		if filterURL != "" {
711			listQuery = listQuery.Where("request_url LIKE ?", "%"+filterURL+"%")
712		}
713		if filterMethod != "" {
714			listQuery = listQuery.Where("request_method = ?", filterMethod)
715		}
716		if filterStatus != "" {
717			if filterStatusNot {
718				listQuery = listQuery.Where("response_status != ?", filterStatus)
719			} else {
720				listQuery = listQuery.Where("response_status = ?", filterStatus)
721			}
722		}
723		if filterProtocolType > 0 {
724			listQuery = listQuery.Where("protocol_type = ?", filterProtocolType)
725		}
726		if filterDstModelName != "" {
727			listQuery = listQuery.Where("dst_model_name = ?", filterDstModelName)
728		}
729		if tools := parseRequestToolsFilter(filterTools); len(tools) > 0 {
730			for _, tool := range tools {
731				likeTool := escapeSQLLikePattern(tool)
732				listQuery = listQuery.Where(
733					"(request_tools = ? OR request_tools LIKE ? ESCAPE '\\\\' OR request_tools LIKE ? ESCAPE '\\\\' OR request_tools LIKE ? ESCAPE '\\\\')",
734					tool,
735					likeTool+",%",
736					"%,"+likeTool+",%",
737					"%,"+likeTool,
738				)
739			}
740		}
741		if filterAgentToolName != "" {
742			listQuery = listQuery.Where("agent_tool_name = ?", filterAgentToolName)
743		}
744		if filterInputTokensNonzero == 1 {
745			listQuery = listQuery.Where("tokens_input_size > 0")
746		} else if filterInputTokensNonzero == 2 {
747			listQuery = listQuery.Where("tokens_input_size = 0")
748		}
749		if filterOutputTokensNonzero == 1 {
750			listQuery = listQuery.Where("tokens_output_size > 0")
751		} else if filterOutputTokensNonzero == 2 {
752			listQuery = listQuery.Where("tokens_output_size = 0")
753		}
754		// v2.0.39：使用 selectTransactionColumns() 统一白名单，禁止任何遗漏 4 个 longtext。
755		result := listQuery.Select(selectTransactionColumns()).
756			Order("id DESC").Limit(pageSize).Offset(offset).Find(&records)
757		if result.Error != nil {
758			return nil, 0, fmt.Errorf("failed to query records: %w", result.Error)
759		}
760		queryElapsed := time.Since(queryStart)
761		totalElapsed := time.Since(startTime)
762	
763		logger.Printf("[DB] QueryAgentHttpTransactions table=%s days=%d total=%d records=%d count=%v query=%v total=%v",
764			tableName, days, total, len(records), countElapsed, queryElapsed, totalElapsed)
765	
766		return records, total, nil
767	}
